head.b:skin:
/**
 * Ikshvaku Vidya Academy — Design Tokens & Variables
 * Rooted in the official IVA seal: Oxford Navy, Warm Ivory, Muted Gold, and Fine Editorial Lines.
 * Designed for ₹0-cost, lightweight, high-performance static rendering.
 */

:root {
  /* Brand Primary Palette (Derived from IVA.jpeg) */
  --color-navy-deep: #071b36;
  --color-navy-dark: #0a2244;
  --color-navy-medium: #11335e;
  --color-navy-light: #1d467a;
  --color-navy-subtle: #e9f0f8;

  /* Neutral & Canvas Tones */
  --color-bg-base: #faf8f5;
  --color-bg-alt: #f3eee6;
  --color-bg-surface: #ffffff;
  --color-bg-surface-translucent: rgba(255, 255, 255, 0.88);
  --color-bg-dark: #071b36;
  --color-bg-dark-alt: #051429;

  /* Typography Colors */
  --color-text-primary: #121d2b;
  --color-text-secondary: #4a5568;
  --color-text-muted: #718096;
  --color-text-light: #f7fafc;
  --color-text-light-secondary: #cbd5e0;
  --color-text-light-muted: #a0aec0;

  /* Subtle Warm Accents */
  --color-accent-gold: #b38642;
  --color-accent-gold-hover: #9b7234;
  --color-accent-gold-subtle: #f9f4ec;
  --color-accent-terracotta: #a6533f;

  /* Borders & Dividers */
  --color-border-hairline: rgba(7, 27, 54, 0.08);
  --color-border-subtle: rgba(7, 27, 54, 0.14);
  --color-border-dark-hairline: rgba(255, 255, 255, 0.1);
  --color-border-gold: rgba(179, 134, 66, 0.35);

  /* Typography Families */
  --font-serif: 'Newsreader', 'Playfair Display', 'Georgia', 'Cambria', serif;
  --font-sans: 'Plus Jakarta Sans', 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
  --font-mono: 'SF Mono', 'Fira Code', 'Courier New', monospace;

  /* Fluid Spacing Scale */
  --space-2xs: clamp(0.25rem, 0.2rem + 0.25vw, 0.375rem);
  --space-xs: clamp(0.5rem, 0.45rem + 0.25vw, 0.75rem);
  --space-sm: clamp(0.75rem, 0.65rem + 0.5vw, 1.125rem);
  --space-md: clamp(1rem, 0.85rem + 0.75vw, 1.5rem);
  --space-lg: clamp(1.5rem, 1.25rem + 1.25vw, 2.5rem);
  --space-xl: clamp(2.25rem, 1.85rem + 2vw, 4rem);
  --space-2xl: clamp(3.5rem, 2.75rem + 3.75vw, 6.5rem);
  --space-3xl: clamp(5rem, 4rem + 5vw, 10rem);

  /* Layout Widths */
  --container-narrow: 760px;
  --container-text: 880px;
  --container-standard: 1160px;
  --container-wide: 1360px;

  /* Transitions & Shadows */
  --transition-fast: 180ms cubic-bezier(0.16, 1, 0.3, 1);
  --transition-normal: 320ms cubic-bezier(0.16, 1, 0.3, 1);
  --transition-slow: 600ms cubic-bezier(0.16, 1, 0.3, 1);

  --shadow-subtle: 0 4px 20px -2px rgba(7, 27, 54, 0.05);
  --shadow-elevated: 0 12px 36px -4px rgba(7, 27, 54, 0.08);
  --shadow-dark: 0 16px 40px -8px rgba(0, 0, 0, 0.4);

  /* Header & Navigation */
  --nav-height: 80px;
}

/**
 * Ikshvaku Vidya Academy — Editorial Typography
 * High-contrast editorial hierarchy: Newsreader (Classical Serif) + Plus Jakarta Sans (Humanist Sans)
 */



html {
  font-size: 16px;
  scroll-behavior: smooth;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  text-rendering: optimizeLegibility;
}

section[id], div[id] {
  scroll-margin-top: calc(var(--nav-height) + 1.25rem);
}

body {
  font-family: var(--font-sans);
  color: var(--color-text-primary);
  background-color: var(--color-bg-base);
  line-height: 1.65;
  font-size: clamp(1rem, 0.96rem + 0.2vw, 1.125rem);
}

/* Eyebrows / Section Indicators */
.eyebrow {
  display: inline-flex;
  align-items: center;
  gap: 0.6rem;
  font-family: var(--font-sans);
  font-size: 0.75rem;
  font-weight: 600;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  color: var(--color-accent-gold);
  margin-bottom: var(--space-sm);
}

.eyebrow::before {
  content: '';
  display: inline-block;
  width: 1.5rem;
  height: 1px;
  background-color: currentColor;
}

.eyebrow-dark {
  color: var(--color-accent-gold);
}

/* Headings */
h1, h2, h3, h4, h5, h6 {
  color: var(--color-navy-deep);
  font-weight: 500;
  line-height: 1.15;
  letter-spacing: -0.02em;
}

.heading-display {
  font-family: var(--font-serif);
  font-size: clamp(2.75rem, 2rem + 4.5vw, 5.75rem);
  font-weight: 400;
  line-height: 1.05;
  letter-spacing: -0.03em;
  margin-bottom: var(--space-md);
}

.heading-display em,
.heading-display .italic {
  font-style: italic;
  font-family: var(--font-serif);
}

.heading-section {
  font-family: var(--font-serif);
  font-size: clamp(2rem, 1.5rem + 2.5vw, 3.75rem);
  font-weight: 400;
  line-height: 1.12;
  letter-spacing: -0.025em;
  margin-bottom: var(--space-md);
}

.heading-sub {
  font-family: var(--font-serif);
  font-size: clamp(1.4rem, 1.2rem + 1vw, 2rem);
  font-weight: 400;
  line-height: 1.25;
  letter-spacing: -0.015em;
}

.heading-light {
  color: var(--color-text-light);
}

/* Lead & Body Paragraphs */
.lead-text {
  font-family: var(--font-sans);
  font-size: clamp(1.125rem, 1.05rem + 0.45vw, 1.35rem);
  line-height: 1.6;
  color: var(--color-text-secondary);
  font-weight: 400;
  max-width: 68ch;
}

.lead-text-serif {
  font-family: var(--font-serif);
  font-size: clamp(1.25rem, 1.15rem + 0.6vw, 1.6rem);
  line-height: 1.55;
  color: var(--color-text-secondary);
  font-weight: 400;
  font-style: normal;
}

.lead-light {
  color: var(--color-text-light-secondary);
}

.text-editorial {
  font-size: 1.0625rem;
  line-height: 1.75;
  color: var(--color-text-secondary);
  margin-bottom: var(--space-md);
}

.text-editorial p + p {
  margin-top: var(--space-md);
}

/* Manifesto Statements */
.statement-large {
  font-family: var(--font-serif);
  font-size: clamp(1.35rem, 1.15rem + 1.2vw, 2.2rem);
  font-weight: 400;
  line-height: 1.35;
  letter-spacing: -0.015em;
  color: var(--color-navy-deep);
}

/* Quotes */
.quote-editorial {
  font-family: var(--font-serif);
  font-size: clamp(1.4rem, 1.2rem + 1.2vw, 2.25rem);
  font-style: italic;
  line-height: 1.4;
  color: var(--color-navy-deep);
  border-left: 2px solid var(--color-accent-gold);
  padding-left: var(--space-md);
  margin: var(--space-lg) 0;
}

.quote-citation {
  display: block;
  font-family: var(--font-sans);
  font-size: 0.8125rem;
  font-style: normal;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--color-accent-gold);
  margin-top: var(--space-xs);
}

/* Links & Text Utilities */
a {
  color: var(--color-navy-deep);
  text-decoration: none;
  transition: color var(--transition-fast);
}

a:hover {
  color: var(--color-accent-gold);
}

.link-editorial {
  display: inline-flex;
  align-items: center;
  gap: 0.4rem;
  font-weight: 600;
  font-size: 0.9375rem;
  color: var(--color-navy-deep);
  border-bottom: 1px solid var(--color-accent-gold);
  padding-bottom: 2px;
  transition: all var(--transition-fast);
}

.link-editorial:hover {
  color: var(--color-accent-gold-hover);
  border-bottom-color: var(--color-navy-deep);
  gap: 0.65rem;
}

.text-center { text-align: center; }
.text-right { text-align: right; }
.text-muted { color: var(--color-text-muted); }
.text-gold { color: var(--color-accent-gold); }

/**
 * Ikshvaku Vidya Academy — Editorial Layout & Grid System
 * Controlled whitespace, asymmetric columns, visual thread line, and breathing spaces.
 */

*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

/* Page Wrapper */
.page-wrapper {
  position: relative;
  width: 100%;
  overflow-x: hidden;
  background-color: var(--color-bg-base);
}

/* Containers */
.container {
  width: 100%;
  max-width: var(--container-standard);
  margin-left: auto;
  margin-right: auto;
  padding-left: clamp(1rem, 0.5rem + 2.5vw, 2.5rem);
  padding-right: clamp(1rem, 0.5rem + 2.5vw, 2.5rem);
}

.container-narrow {
  max-width: var(--container-narrow);
}

.container-text {
  max-width: var(--container-text);
}

.container-wide {
  max-width: var(--container-wide);
}

/* Section Spacing */
.section {
  position: relative;
  padding-top: var(--space-2xl);
  padding-bottom: var(--space-2xl);
}

.section-spacious {
  padding-top: var(--space-3xl);
  padding-bottom: var(--space-3xl);
}

.section-compact {
  padding-top: var(--space-xl);
  padding-bottom: var(--space-xl);
}

/* Background Variations */
.bg-base {
  background-color: var(--color-bg-base);
}

.bg-alt {
  background-color: var(--color-bg-alt);
}

.bg-surface {
  background-color: var(--color-bg-surface);
}

.bg-dark {
  background-color: var(--color-bg-dark);
  color: var(--color-text-light);
}

.bg-dark-alt {
  background-color: var(--color-bg-dark-alt);
  color: var(--color-text-light);
}

/* Hairline Dividers */
.divider-hairline {
  width: 100%;
  height: 1px;
  background-color: var(--color-border-hairline);
  margin: 0;
  border: none;
}

.divider-gold {
  width: 3.5rem;
  height: 2px;
  background-color: var(--color-accent-gold);
  border: none;
  margin: var(--space-md) 0;
}

.divider-gold.centered {
  margin-left: auto;
  margin-right: auto;
}

.divider-dark {
  background-color: var(--color-border-dark-hairline);
}

/* Editorial Two-Column & Asymmetric Grids */
.editorial-grid-2col {
  display: grid;
  grid-template-columns: 1fr;
  gap: var(--space-lg);
  align-items: start;
}

@media (min-width: 860px) {
  .editorial-grid-2col {
    grid-template-columns: 1fr 1fr;
    gap: var(--space-xl);
  }
}

.editorial-grid-asym {
  display: grid;
  grid-template-columns: 1fr;
  gap: var(--space-lg);
}

@media (min-width: 960px) {
  .editorial-grid-asym {
    grid-template-columns: 5fr 7fr;
    gap: var(--space-xl);
  }

  .editorial-grid-asym.reverse {
    grid-template-columns: 7fr 5fr;
  }
}

.editorial-grid-3col {
  display: grid;
  grid-template-columns: 1fr;
  gap: var(--space-md);
}

@media (min-width: 680px) {
  .editorial-grid-3col {
    grid-template-columns: repeat(2, 1fr);
  }
}

@media (min-width: 1024px) {
  .editorial-grid-3col {
    grid-template-columns: repeat(3, 1fr);
    gap: var(--space-lg);
  }
}

/* Visual Narrative Thread Line */
.narrative-thread-container {
  position: relative;
}

.narrative-thread-line {
  position: absolute;
  left: 2rem;
  top: 0;
  bottom: 0;
  width: 1px;
  background: linear-gradient(
    to bottom,
    transparent 0%,
    var(--color-accent-gold) 15%,
    var(--color-navy-deep) 50%,
    var(--color-accent-gold) 85%,
    transparent 100%
  );
  opacity: 0.25;
  display: none;
}

@media (min-width: 1200px) {
  .narrative-thread-line {
    display: block;
  }
}

/* Breathing Moments / Editorial Pauses */
.section-pause {
  padding-top: var(--space-3xl);
  padding-bottom: var(--space-3xl);
  display: flex;
  align-items: center;
  justify-content: center;
  text-align: center;
  position: relative;
  background-color: var(--color-bg-base);
}

.pause-content {
  max-width: 720px;
  margin: 0 auto;
}

.pause-quote {
  font-family: var(--font-serif);
  font-size: clamp(1.6rem, 1.3rem + 1.8vw, 3rem);
  line-height: 1.35;
  font-weight: 400;
  color: var(--color-navy-deep);
  margin-bottom: var(--space-md);
  letter-spacing: -0.02em;
}

.pause-subtext {
  font-family: var(--font-sans);
  font-size: 0.9375rem;
  letter-spacing: 0.15em;
  text-transform: uppercase;
  color: var(--color-accent-gold);
}

/**
 * Ikshvaku Vidya Academy ? Editorial Components
 * Institutional, refined, human, and responsive.
 */

/* ==========================================================================
   1. SITE HEADER & NAVIGATION
   ========================================================================== */
.site-header {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  height: var(--nav-height);
  background-color: var(--color-bg-surface-translucent);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  border-bottom: 1px solid var(--color-border-hairline);
  z-index: 1000;
  transition: all var(--transition-normal);
}

.site-header.scrolled {
  background-color: rgba(250, 248, 245, 0.96);
  box-shadow: var(--shadow-subtle);
  height: 70px;
}

.header-container {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 100%;
}

.brand-link {
  display: flex;
  align-items: center;
  gap: 0.85rem;
  text-decoration: none;
}

.brand-logo-img {
  width: 44px;
  height: 44px;
  object-fit: contain;
  border-radius: 4px;
  border: 1px solid rgba(7, 27, 54, 0.12);
  background-color: #ffffff;
  padding: 1px;
}

.brand-meta {
  display: flex;
  flex-direction: column;
}

.brand-name {
  font-family: var(--font-serif);
  font-size: 1.15rem;
  font-weight: 600;
  color: var(--color-navy-deep);
  line-height: 1.1;
  letter-spacing: -0.01em;
}

.brand-tagline {
  font-size: 0.6875rem;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--color-accent-gold);
  font-weight: 600;
}

.nav-desktop {
  display: none;
  align-items: center;
  gap: 2rem;
}

@media (min-width: 992px) {
  .nav-desktop {
    display: flex;
  }
}

.nav-link {
  font-size: 0.875rem;
  font-weight: 500;
  letter-spacing: 0.04em;
  color: var(--color-text-secondary);
  transition: color var(--transition-fast);
  position: relative;
  padding: 0.5rem 0;
}

.nav-link:hover {
  color: var(--color-navy-deep);
}

.nav-link::after {
  content: '';
  position: absolute;
  bottom: 0;
  left: 0;
  width: 0;
  height: 1px;
  background-color: var(--color-accent-gold);
  transition: width var(--transition-fast);
}

.nav-link:hover::after {
  width: 100%;
}

.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.5rem;
  padding: 0.75rem 1.6rem;
  font-family: var(--font-sans);
  font-size: 0.875rem;
  font-weight: 600;
  letter-spacing: 0.04em;
  border-radius: 2px;
  text-decoration: none;
  cursor: pointer;
  transition: all var(--transition-fast);
  border: 1px solid transparent;
}

.btn-primary {
  background-color: var(--color-navy-deep);
  color: #ffffff;
}

.btn-primary:hover {
  background-color: var(--color-navy-dark);
  color: #ffffff;
  transform: translateY(-1px);
  box-shadow: 0 4px 12px rgba(7, 27, 54, 0.15);
}

.btn-secondary {
  background-color: transparent;
  color: var(--color-navy-deep);
  border-color: var(--color-border-subtle);
}

.btn-secondary:hover {
  border-color: var(--color-navy-deep);
  background-color: rgba(7, 27, 54, 0.03);
}

.btn-gold {
  background-color: var(--color-accent-gold);
  color: #ffffff;
}

.btn-gold:hover {
  background-color: var(--color-accent-gold-hover);
  color: #ffffff;
}

/* Mobile Navigation Hamburger */
.mobile-menu-toggle {
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  gap: 5px;
  width: 44px;
  height: 44px;
  background: transparent;
  border: 1px solid var(--color-border-hairline);
  border-radius: 4px;
  cursor: pointer;
  padding: 0;
}

@media (min-width: 992px) {
  .mobile-menu-toggle {
    display: none;
  }
}

.mobile-menu-toggle span {
  display: block;
  width: 20px;
  height: 1.5px;
  background-color: var(--color-navy-deep);
  transition: all var(--transition-fast);
}

.mobile-drawer {
  position: fixed;
  top: var(--nav-height);
  left: 0;
  right: 0;
  width: 100%;
  height: calc(100vh - var(--nav-height));
  height: calc(100dvh - var(--nav-height));
  background-color: #faf8f5 !important;
  background: #faf8f5 !important;
  border-top: 1px solid rgba(7, 27, 54, 0.12);
  padding: 2.5rem 1.75rem 3rem;
  display: flex;
  flex-direction: column;
  gap: 1.75rem;
  transform: translateY(-120%);
  opacity: 0;
  pointer-events: none;
  transition: transform 0.32s cubic-bezier(0.16, 1, 0.3, 1), opacity 0.25s ease;
  z-index: 99999 !important;
  overflow-y: auto;
  -webkit-overflow-scrolling: touch;
  box-shadow: 0 20px 40px rgba(7, 27, 54, 0.15);
}

.mobile-drawer.open {
  transform: translateY(0);
  opacity: 1;
  pointer-events: auto;
}

.mobile-drawer .nav-link {
  font-family: var(--font-serif);
  font-size: 1.5rem;
  color: var(--color-navy-deep);
  border-bottom: 1px solid var(--color-border-hairline);
  padding-bottom: 0.75rem;
}

/* ==========================================================================
   2. HERO EXPERIENCE
   ========================================================================== */
.hero-section {
  padding-top: calc(var(--nav-height) + var(--space-2xl));
  padding-bottom: var(--space-3xl);
  min-height: 85vh;
  display: flex;
  align-items: center;
  position: relative;
  background: radial-gradient(circle at 50% 20%, rgba(243, 238, 230, 0.85) 0%, var(--color-bg-base) 70%);
}

.hero-seal-container {
  display: flex;
  justify-content: center;
  margin-bottom: var(--space-lg);
}

.hero-seal-frame {
  position: relative;
  width: 140px;
  height: 140px;
  border-radius: 8px;
  padding: 6px;
  background: #ffffff;
  border: 1px solid var(--color-border-subtle);
  box-shadow: var(--shadow-subtle);
}

@media (min-width: 768px) {
  .hero-seal-frame {
    width: 168px;
    height: 168px;
  }
}

.hero-seal-img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  border-radius: 4px;
}

.hero-tagline-pill {
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  padding: 0.35rem 1rem;
  border-radius: 100px;
  background-color: var(--color-accent-gold-subtle);
  border: 1px solid var(--color-border-gold);
  font-size: 0.75rem;
  font-weight: 600;
  letter-spacing: 0.15em;
  text-transform: uppercase;
  color: var(--color-accent-gold-hover);
  margin-bottom: var(--space-md);
}

.hero-actions {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 1rem;
  margin-top: var(--space-lg);
}

/* ==========================================================================
   3. THE TRIAD OF IKSHVAKU (Quality, Facilities, Affordability)
   ========================================================================== */
.triad-grid {
  display: grid;
  grid-template-columns: 1fr;
  gap: var(--space-md);
  margin-top: var(--space-xl);
}

@media (min-width: 860px) {
  .triad-grid {
    grid-template-columns: repeat(3, 1fr);
  }
}

.triad-card {
  background-color: var(--color-bg-surface);
  border: 1px solid var(--color-border-subtle);
  padding: var(--space-lg);
  position: relative;
  transition: transform var(--transition-fast), box-shadow var(--transition-fast);
}

.triad-card:hover {
  transform: translateY(-3px);
  box-shadow: var(--shadow-subtle);
}

.triad-number {
  font-family: var(--font-serif);
  font-size: 2.25rem;
  color: var(--color-accent-gold);
  line-height: 1;
  margin-bottom: var(--space-sm);
  opacity: 0.85;
}

.triad-card h3 {
  font-family: var(--font-serif);
  font-size: 1.5rem;
  color: var(--color-navy-deep);
  margin-bottom: var(--space-xs);
}

.triad-card p {
  font-size: 0.9375rem;
  color: var(--color-text-secondary);
  line-height: 1.65;
}

/* ==========================================================================
   4. EMOTIONAL SECTION: "THERE IS A STUDENT"
   ========================================================================== */
.student-monologue {
  background-color: var(--color-bg-alt);
  border-top: 1px solid var(--color-border-hairline);
  border-bottom: 1px solid var(--color-border-hairline);
  padding: var(--space-3xl) 0;
}

.student-narrative-frame {
  max-width: 820px;
  margin: 0 auto;
}

.student-observation-list {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 1.25rem;
  margin: var(--space-xl) 0;
}

.student-observation-item {
  display: flex;
  align-items: baseline;
  gap: 1rem;
  font-family: var(--font-serif);
  font-size: clamp(1.15rem, 1rem + 0.6vw, 1.5rem);
  line-height: 1.5;
  color: var(--color-navy-deep);
}

.student-bullet {
  display: inline-block;
  width: 6px;
  height: 6px;
  background-color: var(--color-accent-gold);
  border-radius: 50%;
  flex-shrink: 0;
  transform: translateY(-2px);
}

/* ==========================================================================
   5. WHY AFFORDABLE (Cheap vs Affordable)
   ========================================================================== */
.comparison-container {
  display: grid;
  grid-template-columns: 1fr;
  gap: var(--space-lg);
  margin-top: var(--space-xl);
}

@media (min-width: 768px) {
  .comparison-container {
    grid-template-columns: 1fr 1fr;
  }
}

.comparison-box {
  padding: var(--space-lg);
  border-radius: 2px;
}

.comparison-box.box-cheap {
  background-color: #ffffff;
  border: 1px solid var(--color-border-subtle);
  border-top: 3px solid #94a3b8;
}

.comparison-box.box-affordable {
  background-color: var(--color-bg-surface);
  border: 1px solid var(--color-border-gold);
  border-top: 3px solid var(--color-accent-gold);
  box-shadow: var(--shadow-subtle);
}

.comparison-label {
  font-size: 0.75rem;
  font-weight: 700;
  letter-spacing: 0.15em;
  text-transform: uppercase;
  margin-bottom: var(--space-xs);
}

.box-cheap .comparison-label {
  color: #64748b;
}

.box-affordable .comparison-label {
  color: var(--color-accent-gold);
}

.comparison-title {
  font-family: var(--font-serif);
  font-size: 1.75rem;
  margin-bottom: var(--space-sm);
  color: var(--color-navy-deep);
}

.comparison-list {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
  margin-top: var(--space-md);
  font-size: 0.9375rem;
  color: var(--color-text-secondary);
}

.comparison-list li {
  display: flex;
  align-items: baseline;
  gap: 0.6rem;
}

/* ==========================================================================
   6. MORE THAN A CLASSROOM (The Learning Progression)
   ========================================================================== */
.learning-flow {
  display: grid;
  grid-template-columns: 1fr;
  gap: 1.5rem;
  margin-top: var(--space-xl);
}

@media (min-width: 600px) {
  .learning-flow {
    grid-template-columns: repeat(2, 1fr);
  }
}

@media (min-width: 1024px) {
  .learning-flow {
    grid-template-columns: repeat(5, 1fr);
  }
}

.flow-step-card {
  background-color: #ffffff;
  border: 1px solid var(--color-border-subtle);
  padding: var(--space-md);
  position: relative;
  transition: all var(--transition-fast);
}

.flow-step-card:hover {
  border-color: var(--color-accent-gold);
}

.flow-step-num {
  font-family: var(--font-sans);
  font-size: 0.6875rem;
  letter-spacing: 0.15em;
  color: var(--color-accent-gold);
  font-weight: 700;
  text-transform: uppercase;
  margin-bottom: 0.5rem;
}

.flow-step-name {
  font-family: var(--font-serif);
  font-size: 1.35rem;
  color: var(--color-navy-deep);
  margin-bottom: 0.5rem;
}

.flow-step-desc {
  font-size: 0.875rem;
  color: var(--color-text-secondary);
  line-height: 1.5;
}

/* ==========================================================================
   7. MANIFESTO ("What We Believe")
   ========================================================================== */
.manifesto-wrapper {
  background-color: var(--color-bg-dark);
  color: var(--color-text-light);
  padding: var(--space-3xl) 0;
  position: relative;
}

.manifesto-grid {
  display: flex;
  flex-direction: column;
  gap: var(--space-lg);
  max-width: 860px;
  margin: var(--space-xl) auto 0;
}

.manifesto-card {
  padding-left: var(--space-md);
  border-left: 1px solid var(--color-accent-gold);
  transition: transform var(--transition-fast);
}

.manifesto-statement {
  font-family: var(--font-serif);
  font-size: clamp(1.3rem, 1.1rem + 1vw, 2rem);
  font-weight: 400;
  line-height: 1.35;
  color: #ffffff;
  letter-spacing: -0.015em;
}

.manifesto-elaboration {
  font-family: var(--font-sans);
  font-size: 0.9375rem;
  color: var(--color-text-light-muted);
  line-height: 1.6;
  margin-top: 0.5rem;
}

/* ==========================================================================
   8. THE STUDENT WE SEE
   ========================================================================== */
.student-see-grid {
  display: grid;
  grid-template-columns: 1fr;
  gap: var(--space-md);
  margin-top: var(--space-xl);
}

@media (min-width: 768px) {
  .student-see-grid {
    grid-template-columns: repeat(2, 1fr);
  }
}

@media (min-width: 1024px) {
  .student-see-grid {
    grid-template-columns: repeat(3, 1fr);
  }
}

.student-see-card {
  background-color: #ffffff;
  border: 1px solid var(--color-border-hairline);
  padding: var(--space-lg);
  transition: all var(--transition-fast);
}

.student-see-card:hover {
  border-color: var(--color-border-subtle);
  box-shadow: var(--shadow-subtle);
}

.student-see-title {
  font-family: var(--font-serif);
  font-size: 1.25rem;
  color: var(--color-navy-deep);
  margin-bottom: 0.5rem;
}

.student-see-text {
  font-size: 0.9375rem;
  color: var(--color-text-secondary);
  line-height: 1.6;
}

/* ==========================================================================
   9. FOUNDERS ("Two People. One Beginning. A Bigger Vision.")
   ========================================================================== */
.founders-container {
  display: grid;
  grid-template-columns: 1fr;
  gap: var(--space-lg);
  margin-top: var(--space-xl);
}

@media (min-width: 768px) {
  .founders-container {
    grid-template-columns: 1fr 1fr;
  }
}

.founder-card {
  background-color: #ffffff;
  border: 1px solid var(--color-border-subtle);
  padding: var(--space-xl);
  position: relative;
}

.founder-role-badge {
  font-family: var(--font-sans);
  font-size: 0.75rem;
  font-weight: 700;
  letter-spacing: 0.15em;
  text-transform: uppercase;
  color: var(--color-accent-gold);
  margin-bottom: 0.5rem;
}

.founder-name {
  font-family: var(--font-serif);
  font-size: 1.75rem;
  color: var(--color-navy-deep);
  margin-bottom: 0.75rem;
}

.founder-quote {
  font-family: var(--font-serif);
  font-style: italic;
  font-size: 1.0625rem;
  line-height: 1.6;
  color: var(--color-text-secondary);
}

/* ==========================================================================
   10. INQUIRY & CONTACT FORM
   ========================================================================== */
.inquiry-wrapper {
  background-color: #ffffff;
  border: 1px solid var(--color-border-subtle);
  padding: var(--space-xl);
  max-width: 780px;
  margin: var(--space-xl) auto 0;
  box-shadow: var(--shadow-subtle);
}

.form-group {
  margin-bottom: var(--space-md);
}

.form-label {
  display: block;
  font-size: 0.8125rem;
  font-weight: 600;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--color-navy-deep);
  margin-bottom: 0.4rem;
}

.form-control {
  width: 100%;
  padding: 0.85rem 1rem;
  font-family: var(--font-sans);
  font-size: 0.9375rem;
  color: var(--color-text-primary);
  background-color: var(--color-bg-base);
  border: 1px solid var(--color-border-subtle);
  border-radius: 2px;
  transition: all var(--transition-fast);
}

.form-control:focus {
  outline: none;
  border-color: var(--color-navy-deep);
  background-color: #ffffff;
  box-shadow: 0 0 0 2px rgba(7, 27, 54, 0.08);
}

.form-row {
  display: grid;
  grid-template-columns: 1fr;
  gap: var(--space-md);
}

@media (min-width: 600px) {
  .form-row {
    grid-template-columns: 1fr 1fr;
  }
}

.form-notice {
  font-size: 0.8125rem;
  color: var(--color-text-muted);
  line-height: 1.5;
  margin-top: var(--space-sm);
}

.form-status {
  margin-top: var(--space-md);
  padding: 0.85rem 1rem;
  border-radius: 2px;
  font-size: 0.875rem;
  display: none;
}

.form-status.success {
  display: block;
  background-color: #ecfdf5;
  color: #065f46;
  border: 1px solid #a7f3d0;
}

.form-status.error {
  display: block;
  background-color: #fef2f2;
  color: #991b1b;
  border: 1px solid #fecaca;
}

/* ==========================================================================
   11. SITE FOOTER
   ========================================================================== */

@media (max-width: 768px) {
  .site-footer {
    padding-top: var(--space-xl) !important;
    padding-bottom: var(--space-lg) !important;
  }
}

.site-footer {
  background-color: var(--color-bg-dark);
  color: var(--color-text-light);
  padding-top: var(--space-3xl);
  padding-bottom: var(--space-xl);
  border-top: 1px solid var(--color-border-dark-hairline);
}

.footer-grid {
  display: grid;
  grid-template-columns: 1fr;
  gap: var(--space-xl);
  margin-bottom: var(--space-2xl);
}

@media (min-width: 860px) {
  .footer-grid {
    grid-template-columns: 2fr 1fr 1fr;
  }
}

.footer-brand-col {
  display: flex;
  flex-direction: column;
  gap: 1rem;
}

.footer-logo-wrap {
  display: flex;
  align-items: center;
  gap: 0.85rem;
}

.footer-logo-img {
  width: 52px;
  height: 52px;
  object-fit: contain;
  border-radius: 4px;
  background-color: #ffffff;
  padding: 2px;
}

.footer-tagline {
  font-size: 0.8125rem;
  letter-spacing: 0.15em;
  text-transform: uppercase;
  color: var(--color-accent-gold);
}

.footer-col-title {
  font-family: var(--font-sans);
  font-size: 0.75rem;
  font-weight: 700;
  letter-spacing: 0.15em;
  text-transform: uppercase;
  color: var(--color-text-light);
  margin-bottom: var(--space-sm);
}

.footer-links {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 0.65rem;
}

.footer-links a {
  color: var(--color-text-light-muted);
  font-size: 0.875rem;
  transition: color var(--transition-fast);
}

.footer-links a:hover {
  color: #ffffff;
}

.footer-bottom {
  display: flex;
  flex-direction: column;
  gap: 1rem;
  padding-top: var(--space-lg);
  border-top: 1px solid var(--color-border-dark-hairline);
  font-size: 0.8125rem;
  color: var(--color-text-light-muted);
}

@media (min-width: 768px) {
  .footer-bottom {
    flex-direction: row;
    justify-content: space-between;
    align-items: center;
  }
}

/**
 * Ikshvaku Vidya Academy ? Subtle Animations & Transitions
 * Respectful, slow, intentional motion. Respects prefers-reduced-motion.
 */

/* Scroll Reveal Classes */
.reveal-on-scroll {
  opacity: 0;
  transform: translateY(24px);
  transition: opacity 0.8s cubic-bezier(0.16, 1, 0.3, 1),
              transform 0.8s cubic-bezier(0.16, 1, 0.3, 1);
  will-change: opacity, transform;
}

.reveal-on-scroll.is-revealed {
  opacity: 1;
  transform: translateY(0);
}

/* Stagger Delays */
.delay-1 { transition-delay: 0.1s; }
.delay-2 { transition-delay: 0.2s; }
.delay-3 { transition-delay: 0.3s; }
.delay-4 { transition-delay: 0.4s; }
.delay-5 { transition-delay: 0.5s; }

/* Subtle Seal Hover */
.hero-seal-frame {
  transition: transform 0.4s cubic-bezier(0.16, 1, 0.3, 1),
              box-shadow 0.4s cubic-bezier(0.16, 1, 0.3, 1);
}

.hero-seal-frame:hover {
  transform: translateY(-2px);
  box-shadow: 0 12px 30px -4px rgba(7, 27, 54, 0.12);
}

/* Subtle Breathing Accent */
@keyframes subtlePulse {
  0%, 100% { opacity: 0.4; }
  50% { opacity: 0.85; }
}

.pulse-accent {
  animation: subtlePulse 4s ease-in-out infinite;
}

/* Accessibility: Strict Reduced Motion */
@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
    scroll-behavior: auto !important;
  }

  .reveal-on-scroll {
    opacity: 1 !important;
    transform: none !important;
  }
}

/**
 * Ikshvaku Vidya Academy — Responsive & Viewport Enhancements
 * Explicit responsive rules for 320px, 375px, 430px, 768px, 1024px, 1440px, and 1920px.
 */

/* ==========================================================================
   1. SMALL MOBILE (320px - 374px)
   ========================================================================== */
@media (max-width: 374px) {
  :root {
    --nav-height: 68px;
  }

  .container {
    padding-left: 0.85rem;
    padding-right: 0.85rem;
  }

  .brand-logo-img {
    width: 36px;
    height: 36px;
  }

  .brand-name {
    font-size: 1.05rem;
  }

  .brand-tagline {
    font-size: 0.625rem;
  }

  .hero-seal-frame {
    width: 120px;
    height: 120px;
    padding: 4px;
  }

  .heading-display {
    font-size: 2.2rem;
  }

  .heading-section {
    font-size: 1.75rem;
  }

  .btn {
    width: 100%;
    padding: 0.75rem 1rem;
    font-size: 0.8125rem;
  }

  .hero-actions {
    flex-direction: column;
    width: 100%;
  }

  .triad-card,
  .flow-step-card,
  .comparison-box,
  .student-see-card,
  .founder-card {
    padding: 1.25rem 1rem;
  }

  .manifesto-card {
    padding-left: 0.75rem;
  }

  .manifesto-statement {
    font-size: 1.2rem;
  }
}

/* ==========================================================================
   2. STANDARD MOBILE (375px - 430px)
   ========================================================================== */
@media (min-width: 375px) and (max-width: 600px) {
  .hero-actions {
    flex-direction: column;
    width: 100%;
  }

  .hero-actions .btn {
    width: 100%;
  }

  .hero-seal-frame {
    width: 136px;
    height: 136px;
  }

  .student-observation-item {
    font-size: 1.15rem;
  }
}

/* ==========================================================================
   3. TABLET & MID-VIEWPORT (601px - 991px)
   ========================================================================== */
@media (min-width: 601px) and (max-width: 991px) {
  .hero-seal-frame {
    width: 150px;
    height: 150px;
  }

  .editorial-grid-asym {
    grid-template-columns: 1fr;
    gap: var(--space-lg);
  }

  .learning-flow {
    grid-template-columns: repeat(2, 1fr);
  }
}

/* ==========================================================================
   4. DESKTOP & LAPTOPS (992px - 1439px)
   ========================================================================== */
@media (min-width: 992px) {
  .site-header {
    height: var(--nav-height);
  }

  .hero-section {
    min-height: 88vh;
  }

  .learning-flow {
    grid-template-columns: repeat(5, 1fr);
  }

  .triad-grid {
    grid-template-columns: repeat(3, 1fr);
  }
}

/* ==========================================================================
   5. WIDE & ULTRA-WIDE DESKTOPS (1440px - 1920px+)
   ========================================================================== */
@media (min-width: 1440px) {
  .container {
    max-width: 1240px;
  }

  .container-text {
    max-width: 920px;
  }

  .heading-display {
    font-size: 5.25rem;
    line-height: 1.04;
  }

  .lead-text {
    font-size: 1.25rem;
    line-height: 1.65;
  }

  .section {
    padding-top: calc(var(--space-2xl) * 1.15);
    padding-bottom: calc(var(--space-2xl) * 1.15);
  }
}

/* ==========================================================================
   6. PRINT STYLESHEET
   ========================================================================== */
@media print {
  .site-header,
  .mobile-menu-toggle,
  .mobile-drawer,
  .hero-actions,
  .footer-bottom {
    display: none !important;
  }

  body {
    background-color: #ffffff;
    color: #000000;
  }

  .section {
    padding-top: 2rem;
    padding-bottom: 2rem;
    page-break-inside: avoid;
  }

  .manifesto-wrapper,
  .site-footer {
    background-color: #ffffff !important;
    color: #000000 !important;
  }

  .heading-light,
  .lead-light,
  .manifesto-statement {
    color: #000000 !important;
  }
}


/* ==========================================================================
   BLOGGER SPECIFIC JOURNAL & POST STYLES
   ========================================================================== */
.journal-section {
  padding: 0;
  margin: 0;
  background-color: var(--color-bg-base);
}

.journal-section .container {
  padding-top: var(--space-xl);
  padding-bottom: var(--space-xl);
}

.journal-header-wrap {
  text-align: center;
  max-width: 780px;
  margin: 0 auto var(--space-2xl);
}

.posts-grid {
  display: grid;
  grid-template-columns: 1fr;
  gap: var(--space-lg);
  margin-top: var(--space-xl);
}

@media (min-width: 768px) {
  .posts-grid {
    grid-template-columns: repeat(2, 1fr);
  }
}

@media (min-width: 1024px) {
  .posts-grid {
    grid-template-columns: repeat(3, 1fr);
  }
}

.post-card {
  background-color: #ffffff;
  border: 1px solid var(--color-border-subtle);
  padding: var(--space-lg);
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  transition: all var(--transition-fast);
}

.post-card:hover {
  transform: translateY(-2px);
  box-shadow: var(--shadow-subtle);
  border-color: var(--color-accent-gold);
}

.post-card-date {
  font-size: 0.75rem;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--color-accent-gold);
  font-weight: 600;
  margin-bottom: 0.5rem;
}

.post-card-title {
  font-family: var(--font-serif);
  font-size: 1.4rem;
  line-height: 1.25;
  color: var(--color-navy-deep);
  margin-bottom: 0.75rem;
}

.post-card-title a {
  color: inherit;
  text-decoration: none;
}

.post-card-title a:hover {
  color: var(--color-accent-gold);
}

.post-card-snippet {
  font-size: 0.9375rem;
  color: var(--color-text-secondary);
  line-height: 1.6;
  margin-bottom: var(--space-md);
  flex-grow: 1;
}

/* Individual Post & Static Page View */
.single-post-container {
  padding-top: calc(var(--nav-height) + var(--space-2xl));
  padding-bottom: var(--space-3xl);
  max-width: 820px;
  margin: 0 auto;
}

.single-post-header {
  margin-bottom: var(--space-xl);
  text-align: center;
}

.single-post-date {
  font-size: 0.8125rem;
  letter-spacing: 0.15em;
  text-transform: uppercase;
  color: var(--color-accent-gold);
  font-weight: 600;
  margin-bottom: 0.75rem;
}

.single-post-title {
  font-family: var(--font-serif);
  font-size: clamp(2rem, 1.6rem + 2vw, 3.25rem);
  line-height: 1.15;
  color: var(--color-navy-deep);
  margin-bottom: var(--space-md);
}

.single-post-body {
  font-size: 1.125rem;
  line-height: 1.8;
  color: var(--color-text-primary);
}

.single-post-body p {
  margin-bottom: var(--space-md);
}

.single-post-body h2,
.single-post-body h3 {
  margin-top: var(--space-xl);
  margin-bottom: var(--space-sm);
  color: var(--color-navy-deep);
}

.single-post-body blockquote {
  font-family: var(--font-serif);
  font-size: 1.35rem;
  font-style: italic;
  line-height: 1.5;
  border-left: 2px solid var(--color-accent-gold);
  padding-left: var(--space-md);
  margin: var(--space-lg) 0;
  color: var(--color-navy-deep);
}

.single-post-body img {
  max-width: 100%;
  height: auto;
  border-radius: 2px;
  margin: var(--space-md) 0;
}

.blog-pager {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-top: var(--space-2xl);
  padding-top: var(--space-lg);
  border-top: 1px solid var(--color-border-hairline);
  font-size: 0.9375rem;
}

.post-feeds, .feed-links, .status-msg-wrap { display: none !important; }
.quickedit { display: none !important; }






/* ==========================================================================
   IKSHVAKU CURIOSITY MACHINE STYLES
   ========================================================================== */
/* ── RESET (scoped) ── */
#iva-curiosity-machine *,
#iva-curiosity-machine *::before,
#iva-curiosity-machine *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

/* ── CSS VARIABLES ── */
#iva-curiosity-machine {
  --iva-primary: #0a0e1a;
  --iva-secondary: #12192c;
  --iva-accent: #e94560;
  --iva-accent2: #f5a623;
  --iva-accent3: #00d2ff;
  --iva-text: #f0f4fc;
  --iva-text-dark: #12192c;
  --iva-card-bg: rgba(255, 255, 255, 0.98);
  --iva-card-shadow: 0 12px 40px rgba(0,0,0,0.25);
  --iva-radius: 16px;
  --iva-radius-sm: 10px;
  --iva-transition: 0.3s cubic-bezier(0.4, 0, 0.2, 1);
  --iva-font: 'Segoe UI', -apple-system, BlinkMacSystemFont, Roboto, system-ui, sans-serif;
  --iva-max-width: 1140px;
  font-family: var(--iva-font);
  color: var(--iva-text);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
  background: radial-gradient(circle at 50% 0%, #162447 0%, #0a0e1a 70%);
  min-height: 100vh;
  position: relative;
  overflow-x: hidden;
}

/* ── COSMIC CANVAS ── */
#iva-curiosity-machine #ivaCosmicCanvas {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  pointer-events: none;
  z-index: 1;
  opacity: 0.65;
}

/* ── CONTAINER ── */
#iva-curiosity-machine .iva-container {
  max-width: var(--iva-max-width);
  margin: 0 auto;
  padding: 0 24px;
  position: relative;
  z-index: 2;
}

/* ── TYPOGRAPHY ── */
#iva-curiosity-machine h1 { font-size: clamp(1.8rem, 5vw, 3.4rem); font-weight: 800; letter-spacing: -0.02em; }
#iva-curiosity-machine h2 { font-size: clamp(1.4rem, 3vw, 2.2rem); font-weight: 700; }
#iva-curiosity-machine h3 { font-size: clamp(1.1rem, 2vw, 1.5rem); font-weight: 600; }
#iva-curiosity-machine p { margin-bottom: 0.8rem; }
#iva-curiosity-machine a { color: var(--iva-accent2); text-decoration: none; transition: var(--iva-transition); }
#iva-curiosity-machine a:hover { color: #ffc107; }

/* ── BUTTONS ── */
#iva-curiosity-machine .iva-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 13px 26px;
  border: none;
  border-radius: var(--iva-radius-sm);
  font-size: 0.95rem;
  font-weight: 600;
  cursor: pointer;
  transition: var(--iva-transition);
  font-family: var(--iva-font);
  text-decoration: none;
  line-height: 1.2;
  position: relative;
  overflow: hidden;
  user-select: none;
}

#iva-curiosity-machine .iva-btn:focus-visible {
  outline: 3px solid var(--iva-accent2);
  outline-offset: 2px;
}

#iva-curiosity-machine .iva-btn-primary {
  background: linear-gradient(135deg, #e94560, #d6334d);
  color: #fff;
  box-shadow: 0 4px 20px rgba(233,69,96,0.35);
}
#iva-curiosity-machine .iva-btn-primary:hover {
  transform: translateY(-2px);
  box-shadow: 0 8px 25px rgba(233,69,96,0.5);
  background: linear-gradient(135deg, #f0506b, #e94560);
}

#iva-curiosity-machine .iva-btn-secondary {
  background: rgba(255,255,255,0.08);
  color: #fff;
  border: 1px solid rgba(255,255,255,0.18);
  backdrop-filter: blur(8px);
}
#iva-curiosity-machine .iva-btn-secondary:hover {
  background: rgba(255,255,255,0.16);
  transform: translateY(-2px);
  border-color: rgba(255,255,255,0.3);
}

#iva-curiosity-machine .iva-btn-outline {
  background: transparent;
  color: var(--iva-accent2);
  border: 2px solid var(--iva-accent2);
}
#iva-curiosity-machine .iva-btn-outline:hover {
  background: var(--iva-accent2);
  color: var(--iva-text-dark);
}

#iva-curiosity-machine .iva-btn-small {
  padding: 8px 16px;
  font-size: 0.85rem;
  border-radius: 8px;
}

/* ── CARDS ── */
#iva-curiosity-machine .iva-card {
  background: var(--iva-card-bg);
  border-radius: var(--iva-radius);
  box-shadow: var(--iva-card-shadow);
  padding: clamp(20px, 4vw, 36px);
  color: var(--iva-text-dark);
  transition: var(--iva-transition);
}

#iva-curiosity-machine .iva-card-dark {
  background: rgba(255,255,255,0.06);
  backdrop-filter: blur(12px);
  color: var(--iva-text);
  border: 1px solid rgba(255,255,255,0.1);
  border-radius: var(--iva-radius);
  padding: clamp(20px, 4vw, 32px);
  transition: var(--iva-transition);
}
#iva-curiosity-machine .iva-card-dark:hover {
  border-color: rgba(255,255,255,0.22);
}

/* ── HEADER ── */
#iva-curiosity-machine .iva-header {
  padding: 16px 0;
  border-bottom: 1px solid rgba(255,255,255,0.08);
  position: sticky;
  top: 0;
  z-index: 100;
  background: rgba(10, 14, 26, 0.92);
  backdrop-filter: blur(16px);
}

#iva-curiosity-machine .iva-header-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  max-width: var(--iva-max-width);
  margin: 0 auto;
  padding: 0 24px;
  gap: 16px;
}

#iva-curiosity-machine .iva-logo {
  display: flex;
  align-items: center;
  gap: 12px;
  cursor: pointer;
  user-select: none;
}

#iva-curiosity-machine .iva-logo img {
  width: 44px;
  height: 44px;
  border-radius: 50%;
  object-fit: cover;
  border: 2px solid rgba(255,255,255,0.2);
  transition: var(--iva-transition);
}

#iva-curiosity-machine .iva-logo:hover img {
  transform: rotate(5deg) scale(1.06);
  border-color: var(--iva-accent2);
}

#iva-curiosity-machine .iva-logo-title {
  font-size: clamp(0.95rem, 2vw, 1.15rem);
  font-weight: 800;
  color: #fff;
  letter-spacing: 0.02em;
}

#iva-curiosity-machine .iva-logo-sub {
  font-size: 0.72rem;
  color: rgba(255,255,255,0.6);
  text-transform: uppercase;
  letter-spacing: 0.08em;
}

#iva-curiosity-machine .iva-header-actions {
  display: flex;
  gap: 8px;
  align-items: center;
}

#iva-curiosity-machine .iva-header-link {
  color: rgba(255,255,255,0.75);
  background: none;
  border: none;
  font-size: 0.85rem;
  font-family: inherit;
  font-weight: 600;
  padding: 7px 12px;
  border-radius: 8px;
  cursor: pointer;
  transition: var(--iva-transition);
  display: inline-flex;
  align-items: center;
  gap: 5px;
}
#iva-curiosity-machine .iva-header-link:hover {
  color: #fff;
  background: rgba(255,255,255,0.1);
}

/* ── LEARNER LEVEL PROGRESS BANNER ── */
#iva-curiosity-machine .iva-level-bar {
  background: rgba(255,255,255,0.04);
  border-bottom: 1px solid rgba(255,255,255,0.06);
  padding: 8px 24px;
  font-size: 0.82rem;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  flex-wrap: wrap;
}
#iva-curiosity-machine .iva-progress-track {
  width: 140px;
  height: 6px;
  background: rgba(255,255,255,0.12);
  border-radius: 10px;
  overflow: hidden;
  display: inline-block;
  vertical-align: middle;
  margin: 0 8px;
}
#iva-curiosity-machine .iva-progress-fill {
  height: 100%;
  background: linear-gradient(90deg, var(--iva-accent), var(--iva-accent2));
  width: 15%;
  transition: width 0.4s ease;
}

/* ── HERO ── */
#iva-curiosity-machine .iva-hero {
  text-align: center;
  padding: clamp(40px, 7vw, 90px) 20px clamp(24px, 4vw, 48px);
  position: relative;
}

#iva-curiosity-machine .iva-hero-title {
  font-size: clamp(2.2rem, 6vw, 4.4rem);
  font-weight: 900;
  line-height: 1.1;
  background: linear-gradient(135deg, #ffffff 40%, var(--iva-accent2) 80%, var(--iva-accent3) 100%);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
  margin-bottom: 14px;
}

#iva-curiosity-machine .iva-hero-sub {
  font-size: clamp(1.05rem, 2.5vw, 1.6rem);
  color: rgba(255,255,255,0.8);
  font-weight: 400;
  margin-bottom: 16px;
}

#iva-curiosity-machine .iva-hero-text {
  max-width: 640px;
  margin: 0 auto 32px;
  color: rgba(255,255,255,0.65);
  font-size: clamp(0.95rem, 1.5vw, 1.1rem);
  line-height: 1.7;
}

#iva-curiosity-machine .iva-hero-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
  justify-content: center;
  margin-bottom: 24px;
}

#iva-curiosity-machine .iva-promise {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: 16px 24px;
  margin-top: 24px;
  font-size: 0.88rem;
  color: rgba(255,255,255,0.55);
}

/* ── SEARCH & JUMP ── */
#iva-curiosity-machine .iva-search-section {
  padding: 0 20px 32px;
  max-width: var(--iva-max-width);
  margin: 0 auto;
}

#iva-curiosity-machine .iva-search-box {
  position: relative;
  max-width: 560px;
  margin: 0 auto;
}

#iva-curiosity-machine .iva-search-box input {
  width: 100%;
  padding: 15px 22px 15px 50px;
  border: 2px solid rgba(255,255,255,0.15);
  border-radius: 50px;
  background: rgba(255,255,255,0.06);
  color: #fff;
  font-size: 1rem;
  font-family: inherit;
  transition: var(--iva-transition);
  outline: none;
}
#iva-curiosity-machine .iva-search-box input:focus {
  border-color: var(--iva-accent2);
  background: rgba(255,255,255,0.12);
  box-shadow: 0 0 25px rgba(245,166,35,0.18);
}

#iva-curiosity-machine .iva-search-icon {
  position: absolute;
  left: 18px;
  top: 50%;
  transform: translateY(-50%);
  font-size: 1.15rem;
  color: rgba(255,255,255,0.45);
}

#iva-curiosity-machine .iva-search-results {
  margin-top: 16px;
  max-width: 560px;
  margin-left: auto;
  margin-right: auto;
}
#iva-curiosity-machine .iva-search-result-item {
  background: rgba(255,255,255,0.08);
  border: 1px solid rgba(255,255,255,0.12);
  border-radius: 12px;
  padding: 14px 18px;
  margin-bottom: 8px;
  cursor: pointer;
  transition: var(--iva-transition);
}
#iva-curiosity-machine .iva-search-result-item:hover {
  background: rgba(255,255,255,0.15);
  transform: translateX(4px);
  border-color: var(--iva-accent2);
}

/* ── BADGES ── */
#iva-curiosity-machine .iva-today-badge {
  display: inline-block;
  padding: 4px 12px;
  border-radius: 20px;
  font-size: 0.75rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  margin-bottom: 12px;
}
#iva-curiosity-machine .iva-badge-space { background: #e3f2fd; color: #1565c0; }
#iva-curiosity-machine .iva-badge-science { background: #e8f5e9; color: #2e7d32; }
#iva-curiosity-machine .iva-badge-math { background: #fff3e0; color: #e65100; }
#iva-curiosity-machine .iva-badge-tech { background: #f3e5f5; color: #6a1b9a; }
#iva-curiosity-machine .iva-badge-thinking { background: #fce4ec; color: #c62828; }
#iva-curiosity-machine .iva-badge-nature { background: #e0f2f1; color: #00695c; }
#iva-curiosity-machine .iva-badge-how { background: #e8eaf6; color: #283593; }
#iva-curiosity-machine .iva-badge-behavior { background: #fff8e1; color: #f57f17; }

/* ── CATEGORIES ── */
#iva-curiosity-machine .iva-categories-section {
  padding: 30px 20px;
  max-width: var(--iva-max-width);
  margin: 0 auto;
}
#iva-curiosity-machine .iva-categories-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(200px, 1fr));
  gap: 14px;
}
#iva-curiosity-machine .iva-category-chip {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 16px 20px;
  background: rgba(255,255,255,0.06);
  border: 1px solid rgba(255,255,255,0.1);
  border-radius: 14px;
  color: #fff;
  cursor: pointer;
  transition: var(--iva-transition);
  font-size: 0.92rem;
  font-weight: 600;
  font-family: inherit;
  text-align: left;
}
#iva-curiosity-machine .iva-category-chip:hover {
  background: rgba(255,255,255,0.14);
  transform: translateY(-3px);
  border-color: var(--iva-accent2);
  box-shadow: 0 8px 24px rgba(0,0,0,0.2);
}

/* ── CURIOSITY DETAIL VIEW ── */
#iva-curiosity-machine .iva-curiosity-view {
  padding: 20px;
  max-width: 820px;
  margin: 0 auto;
}
#iva-curiosity-machine .iva-curiosity-question {
  font-size: clamp(1.3rem, 3.5vw, 2.1rem);
  font-weight: 800;
  margin-bottom: 18px;
  line-height: 1.3;
}
#iva-curiosity-machine .iva-think-input {
  width: 100%;
  padding: 14px 18px;
  border: 2px solid #e0e0e0;
  border-radius: 12px;
  font-size: 0.98rem;
  font-family: inherit;
  resize: vertical;
  min-height: 95px;
  transition: var(--iva-transition);
  outline: none;
  background: #fafafa;
}
#iva-curiosity-machine .iva-think-input:focus {
  border-color: var(--iva-accent);
  box-shadow: 0 0 0 4px rgba(233,69,96,0.12);
  background: #fff;
}

#iva-curiosity-machine .iva-explanation-level {
  padding: 18px 22px;
  background: #f8f9fc;
  border-radius: 12px;
  margin-bottom: 14px;
  border-left: 4px solid var(--iva-accent);
  line-height: 1.7;
}
#iva-curiosity-machine .iva-explanation-level h4 {
  font-size: 0.88rem;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  color: var(--iva-accent);
  margin-bottom: 8px;
  font-weight: 700;
}

#iva-curiosity-machine .iva-what-if-box {
  background: linear-gradient(135deg, #fff3e0, #ffe0b2);
  border-radius: 12px;
  padding: 20px;
  margin: 16px 0;
  border: 1px solid rgba(245,166,35,0.3);
}
#iva-curiosity-machine .iva-real-life-box {
  background: #e8f5e9;
  border-radius: 12px;
  padding: 20px;
  margin: 16px 0;
}
#iva-curiosity-machine .iva-connected-box {
  background: #e3f2fd;
  border-radius: 12px;
  padding: 20px;
  margin: 16px 0;
}
#iva-curiosity-machine .iva-connected-tags {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin-top: 10px;
}
#iva-curiosity-machine .iva-connected-tag {
  padding: 5px 14px;
  background: #bbdefb;
  color: #0d47a1;
  border: none;
  border-radius: 20px;
  font-size: 0.85rem;
  font-weight: 600;
  cursor: pointer;
  transition: var(--iva-transition);
  font-family: inherit;
}
#iva-curiosity-machine .iva-connected-tag:hover {
  background: #90caf9;
  transform: translateY(-1px);
}

/* ── INTERACTIVE CANVAS SIMULATOR ── */
#iva-curiosity-machine .iva-sim-box {
  background: #0d1322;
  border-radius: 14px;
  padding: 20px;
  margin: 20px 0;
  border: 1px solid rgba(0, 210, 255, 0.25);
  color: #fff;
}
#iva-curiosity-machine #ivaSimCanvas {
  width: 100%;
  height: 200px;
  border-radius: 10px;
  background: #060911;
  margin: 12px 0;
  display: block;
}

/* ── SAVED GRID ── */
#iva-curiosity-machine .iva-saved-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));
  gap: 16px;
}
#iva-curiosity-machine .iva-saved-item {
  background: rgba(255,255,255,0.06);
  border: 1px solid rgba(255,255,255,0.1);
  border-radius: var(--iva-radius-sm);
  padding: 20px;
  cursor: pointer;
  transition: var(--iva-transition);
}
#iva-curiosity-machine .iva-saved-item:hover {
  background: rgba(255,255,255,0.12);
  transform: translateY(-3px);
  border-color: var(--iva-accent2);
}

/* ── UTILITIES ── */
#iva-curiosity-machine .iva-hidden { display: none !important; }
#iva-curiosity-machine .iva-view { animation: ivaFadeIn 0.35s cubic-bezier(0.4, 0, 0.2, 1); }
#iva-curiosity-machine .iva-view.iva-hidden { display: none !important; }

/* ── TOAST ── */
#iva-curiosity-machine .iva-toast {
  position: fixed;
  bottom: 30px;
  left: 50%;
  transform: translateX(-50%);
  background: #ffffff;
  color: #12192c;
  padding: 12px 24px;
  border-radius: 50px;
  box-shadow: 0 10px 35px rgba(0,0,0,0.3);
  z-index: 3000;
  font-weight: 600;
  font-size: 0.92rem;
  display: flex;
  align-items: center;
  gap: 10px;
  animation: ivaSlideUp 0.3s ease;
  pointer-events: none;
}

/* ── MODALS ── */
#iva-curiosity-machine .iva-overlay {
  position: fixed;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  background: rgba(0,0,0,0.7);
  backdrop-filter: blur(6px);
  z-index: 2000;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 20px;
}
#iva-curiosity-machine .iva-modal {
  background: #fff;
  border-radius: var(--iva-radius);
  padding: clamp(24px, 5vw, 40px);
  max-width: 580px;
  width: 100%;
  max-height: 85vh;
  overflow-y: auto;
  color: var(--iva-text-dark);
  position: relative;
  animation: ivaSlideUp 0.3s ease;
}

@keyframes ivaFadeIn { from { opacity: 0; } to { opacity: 1; } }
@keyframes ivaSlideUp {
  from { opacity: 0; transform: translate(-50%, 15px); }
  to { opacity: 1; transform: translate(-50%, 0); }
}

@media (max-width: 640px) {
  #iva-curiosity-machine .iva-header-inner { flex-direction: column; align-items: flex-start; }
  #iva-curiosity-machine .iva-header-actions { width: 100%; overflow-x: auto; padding-bottom: 4px; }
  #iva-curiosity-machine .iva-level-bar { font-size: 0.75rem; }
}

/* ── PHONE & DESKTOP RESPONSIVE ENHANCEMENTS ── */
@media (max-width: 991px) {
  #iva-curiosity-machine {
    padding: 1.5rem 1rem !important;
  }
  #iva-curiosity-machine .iva-header-inner {
    flex-direction: column;
    align-items: stretch;
    gap: 14px;
  }
  #iva-curiosity-machine .iva-header-actions {
    display: flex;
    flex-wrap: wrap;
    gap: 8px;
    justify-content: flex-start;
  }
  #iva-curiosity-machine .iva-hero-title {
    font-size: clamp(1.75rem, 5vw, 2.5rem) !important;
  }
}

@media (max-width: 640px) {
  #iva-curiosity-machine {
    padding: 1rem 0.5rem !important;
  }
  #iva-curiosity-machine .iva-categories-grid {
    grid-template-columns: repeat(2, 1fr) !important;
    gap: 8px !important;
  }
  #iva-curiosity-machine .iva-category-chip {
    padding: 12px 10px !important;
    font-size: 0.8rem !important;
    flex-direction: column;
    text-align: center;
    gap: 6px;
  }
  #iva-curiosity-machine .iva-curiosity-card {
    padding: 1.25rem 1rem !important;
    border-radius: 16px !important;
  }
  #iva-curiosity-machine .iva-hero-actions {
    flex-direction: column;
    width: 100%;
  }
  #iva-curiosity-machine .iva-hero-actions .iva-btn {
    width: 100%;
    justify-content: center;
  }
  #iva-curiosity-machine .iva-card-actions {
    flex-direction: column;
    width: 100%;
  }
  #iva-curiosity-machine .iva-card-actions .iva-btn {
    width: 100%;
    justify-content: center;
  }
  #iva-curiosity-machine .iva-modal-content {
    width: 95vw !important;
    max-height: 90vh !important;
    padding: 1.25rem 1rem !important;
    margin: 8px !important;
  }
  #iva-curiosity-machine #ivaExportCardCanvas {
    max-width: 100% !important;
    height: auto !important;
  }
  #iva-curiosity-machine .iva-saved-grid {
    grid-template-columns: 1fr !important;
  }
}

@media (max-width: 400px) {
  #iva-curiosity-machine .iva-categories-grid {
    grid-template-columns: 1fr !important;
  }
}

body.script:
//

document.addEventListener('DOMContentLoaded', function() {
  var header = document.querySelector('.site-header');
  if (header) {
    window.addEventListener('scroll', function() {
      if (window.scrollY > 40) {
        header.classList.add('scrolled');
      } else {
        header.classList.remove('scrolled');
      }
    }, { passive: true });
  }

  var toggleBtn = document.querySelector('.mobile-menu-toggle');
  var drawer = document.querySelector('.mobile-drawer');
  if (toggleBtn && drawer) {
    toggleBtn.addEventListener('click', function() {
      var isOpen = drawer.classList.contains('open');
      drawer.classList.toggle('open', !isOpen);
      toggleBtn.setAttribute('aria-expanded', !isOpen ? 'true' : 'false');
      drawer.setAttribute('aria-hidden', isOpen ? 'true' : 'false');
      document.body.style.overflow = !isOpen ? 'hidden' : '';
    });

    drawer.querySelectorAll('a').forEach(function(link) {
      link.addEventListener('click', function() {
        drawer.classList.remove('open');
        toggleBtn.setAttribute('aria-expanded', 'false');
        drawer.setAttribute('aria-hidden', 'true');
        document.body.style.overflow = '';
      });
    });

    document.addEventListener('keydown', function(e) {
      if (e.key === 'Escape' && drawer.classList.contains('open')) {
        drawer.classList.remove('open');
        toggleBtn.setAttribute('aria-expanded', 'false');
        drawer.setAttribute('aria-hidden', 'true');
        document.body.style.overflow = '';
        toggleBtn.focus();
      }
    });
  }


  // Smooth scroll for internal anchor links
  document.querySelectorAll('a[href*="#"]').forEach(function(anchor) {
    anchor.addEventListener('click', function(e) {
      var href = this.getAttribute('href');
      var hashIndex = href.indexOf('#');
      if (hashIndex !== -1) {
        var hash = href.substring(hashIndex);
        var target = document.querySelector(hash);
        if (target) {
          e.preventDefault();
          target.scrollIntoView({ behavior: 'smooth' });
          if (history.pushState) {
            history.pushState(null, null, hash);
          }
        }
      }
    });
  });

  var reveals = document.querySelectorAll('.reveal-on-scroll');
  if (reveals.length) {
    if ('IntersectionObserver' in window) {
      var observer = new IntersectionObserver(function(entries, obs) {
        entries.forEach(function(entry) {
          if (entry.isIntersecting) {
            entry.target.classList.add('is-revealed');
            obs.unobserve(entry.target);
          }
        });
      }, { rootMargin: '0px 0px -40px 0px', threshold: 0.1 });
      reveals.forEach(function(el) { observer.observe(el); });
    } else {
