// ════════════════════════════════════════════════════════════════ // 3. AMBIENT COSMIC PARTICLE CANVAS (60 FPS) // ════════════════════════════════════════════════════════════════ var stars = []; function initCosmicCanvas() { var canvas = document.getElementById('ivaCosmicCanvas'); if (!canvas) return; var ctx = canvas.getContext('2d'); var w = canvas.width = window.innerWidth; var h = canvas.height = window.innerHeight;
window.addEventListener('resize', function() { w = canvas.width = window.innerWidth; h = canvas.height = window.innerHeight; });
stars = []; for (var i = 0; i < 70; i++) { stars.push({ x: Math.random() * w, y: Math.random() * h, r: Math.random() * 1.5 + 0.5, alpha: Math.random() * 0.7 + 0.2, dx: (Math.random() - 0.5) * 0.25, dy: (Math.random() - 0.5) * 0.25 }); }
function animate() { ctx.clearRect(0, 0, w, h); ctx.fillStyle = '#ffffff'; for (var j = 0; j < stars.length; j++) { var s = stars[j]; s.x += s.dx; s.y += s.dy; if (s.x < 0) s.x = w; if (s.x > w) s.x = 0; if (s.y < 0) s.y = h; if (s.y > h) s.y = 0;
ctx.globalAlpha = s.alpha; ctx.beginPath(); ctx.arc(s.x, s.y, s.r, 0, Math.PI * 2); ctx.fill(); } requestAnimationFrame(animate); } animate(); }
