var osc = audioCtx.createOscillator(); var gain = audioCtx.createGain(); osc.connect(gain); gain.connect(audioCtx.destination);
var now = audioCtx.currentTime;
if (type === 'click') { osc.type = 'sine'; osc.frequency.setValueAtTime(520, now); osc.frequency.exponentialRampToValueAtTime(840, now + 0.05); gain.gain.setValueAtTime(0.08, now); gain.gain.exponentialRampToValueAtTime(0.001, now + 0.05); osc.start(now); osc.stop(now + 0.05); } else if (type === 'discover') { osc.type = 'triangle'; osc.frequency.setValueAtTime(440, now); osc.frequency.setValueAtTime(554.37, now + 0.08); osc.frequency.setValueAtTime(659.25, now + 0.16); gain.gain.setValueAtTime(0.12, now); gain.gain.exponentialRampToValueAtTime(0.001, now + 0.35); osc.start(now); osc.stop(now + 0.35); } else if (type === 'reveal') { osc.type = 'sine'; osc.frequency.setValueAtTime(320, now); osc.frequency.exponentialRampToValueAtTime(640, now + 0.2); gain.gain.setValueAtTime(0.15, now); gain.gain.exponentialRampToValueAtTime(0.001, now + 0.25); osc.start(now); osc.stop(now + 0.25); } } catch(e) {} }
// ════════════════════════════════════════════════════════════════ // 5. INTERACTIVE CANVAS SIMULATOR (ORBITS & WAVES) // ════════════════════════════════════════════════════════════════ var simAngle = 0; var simSpeed = 0.03; var simMode = 'orbit';
function initSimCanvas() { var canvas = document.getElementById('ivaSimCanvas'); if (!canvas) return; var ctx = canvas.getContext('2d');
function draw() { var w = canvas.width = canvas.parentElement.clientWidth || 600; var h = canvas.height = 180; ctx.clearRect(0, 0, w, h);
var cx = w / 2; var cy = h / 2;
if (simMode === 'orbit') { // Star in center ctx.fillStyle = '#f5a623'; ctx.shadowColor = '#f5a623'; ctx.shadowBlur = 20; ctx.beginPath(); ctx.arc(cx, cy, 14, 0, Math.PI * 2); ctx.fill(); ctx.shadowBlur = 0;
// Orbit path var rx = 140; var ry = 60; ctx.strokeStyle = 'rgba(255,255,255,0.18)'; ctx.lineWidth = 1.5; ctx.beginPath(); ctx.ellipse(cx, cy, rx, ry, 0, 0, Math.PI * 2); ctx.stroke();
// Planet simAngle += simSpeed; var px = cx + Math.cos(simAngle) * rx; var py = cy + Math.sin(simAngle) * ry;
ctx.fillStyle = '#00d2ff'; ctx.shadowColor = '#00d2ff'; ctx.shadowBlur = 12; ctx.beginPath(); ctx.arc(px, py, 7, 0, Math.PI * 2); ctx.fill(); ctx.shadowBlur = 0;
// Velocity vector arrow var vx = -Math.sin(simAngle) * 24; var vy = Math.cos(simAngle) * 12; ctx.strokeStyle = '#e94560'; ctx.lineWidth = 2; ctx.beginPath(); ctx.moveTo(px, py); ctx.lineTo(px + vx, py + vy); ctx.stroke();
} else { // Wave Phase Inversion ctx.lineWidth = 2; var step = 4; // Wave 1 ctx.strokeStyle = '#00d2ff'; ctx.beginPath(); for (var x = 0; x < w; x += step) { var y1 = cy + Math.sin((x * 0.04) + simAngle) * 35; if (x === 0) ctx.moveTo(x, y1); else ctx.lineTo(x, y1); } ctx.stroke();
// Wave 2 (Anti-Wave) simAngle += simSpeed; ctx.strokeStyle = '#e94560'; ctx.beginPath(); for (var x2 = 0; x2 < w; x2 += step) { var y2 = cy + Math.sin((x2 * 0.04) + simAngle + Math.PI) * 35; if (x2 === 0) ctx.moveTo(x2, y2); else ctx.lineTo(x2, y2); } ctx.stroke();
// Net Result Line (Flat Zero) ctx.strokeStyle = '#2e7d32'; ctx.lineWidth = 2; ctx.setLineDash([4, 4]); ctx.beginPath(); ctx.moveTo(0, cy); ctx.lineTo(w, cy); ctx.stroke(); ctx.setLineDash([]); }
requestAnimationFrame(draw); } draw(); }
// ════════════════════════════════════════════════════════════════ // 6. INSIGHT CARD PNG EXPORT (CANVAS GRAPHIC) // ════════════════════════════════════════════════════════════════ function generateInsightCardPng(questionObj, userThought) { var canvas = document.getElementById('ivaExportCardCanvas'); if (!canvas) return; var ctx = canvas.getContext('2d'); var w = canvas.width = 640; var h = canvas.height = 420;
// Dark sleek background var grad = ctx.createLinearGradient(0, 0, w, h); grad.addColorStop(0, '#101626'); grad.addColorStop(1, '#060a12'); ctx.fillStyle = grad; ctx.fillRect(0, 0, w, h);
// Accent frame border ctx.strokeStyle = '#f5a623'; ctx.lineWidth = 3; ctx.strokeRect(16, 16, w - 32, h - 32);
// Header badge ctx.fillStyle = '#f5a623'; ctx.font = 'bold 13px system-ui, sans-serif'; ctx.fillText("IKSHVAKU CURIOSITY MACHINE • EDUCATION BEYOND COMMERCE", 36, 50);
// Category ctx.fillStyle = '#e94560'; ctx.font = 'bold 12px system-ui, sans-serif'; ctx.fillText((questionObj.categoryLabel || "DISCIPLINE").toUpperCase() + " • " + (questionObj.id || ""), 36, 75);
// Question title wrapped ctx.fillStyle = '#ffffff'; ctx.font = 'bold 20px system-ui, sans-serif'; wrapText(ctx, questionObj.question || "Curiosity Inquiry", 36, 115, w - 72, 28);
// Divider ctx.strokeStyle = 'rgba(255,255,255,0.15)'; ctx.lineWidth = 1; ctx.beginPath(); ctx.moveTo(36, 215); ctx.lineTo(w - 36, 215); ctx.stroke();
// User Thought ctx.fillStyle = '#f5a623'; ctx.font = 'italic 13px system-ui, sans-serif'; ctx.fillText("Student Reflection:", 36, 240);
ctx.fillStyle = '#d0d7e5'; ctx.font = '15px system-ui, sans-serif'; var thoughtText = userThought || "An inquiry into fundamental nature and first-principles mechanisms."; wrapText(ctx, '"' + thoughtText + '"', 36, 270, w - 72, 24);
// Footer signature ctx.fillStyle = 'rgba(255,255,255,0.45)'; ctx.font = '12px system-ui, sans-serif'; ctx.fillText("Ikshvaku Vidya Academy • 500,000 Questions Library", 36, 385); }
function wrapText(ctx, text, x, y, maxWidth, lineHeight) { var words = text.split(' '); var line = ''; for (var n = 0; n < words.length; n++) { var testLine = line + words[n] + ' '; var metrics = ctx.measureText(testLine); if (metrics.width > maxWidth && n > 0) { ctx.fillText(line, x, y); line = words[n] + ' '; y += lineHeight; } else { line = testLine; } } ctx.fillText(line, x, y); }
// ════════════════════════════════════════════════════════════════ // 7. APP STATE & LOCAL STORAGE // ════════════════════════════════════════════════════════════════ var STORAGE_KEY = 'iva_curiosity_store_v2'; var appState = { currentView: 'home', currentQuestionId: null, currentQuestionObj: null, currentCategory: null, exploredIds: [], savedIds: [], reflections: {}, sparkQuestions: [], streak: 1, lastActiveDate: new Date().toDateString() };
function loadState() { try { var raw = localStorage.getItem(STORAGE_KEY); if (raw) { var parsed = JSON.parse(raw); appState.exploredIds = parsed.exploredIds || []; appState.savedIds = parsed.savedIds || []; appState.reflections = parsed.reflections || {}; appState.sparkQuestions = parsed.sparkQuestions || []; appState.streak = parsed.streak || 1; appState.lastActiveDate = parsed.lastActiveDate || new Date().toDateString(); } } catch(e) {} }
function saveState() { try { localStorage.setItem(STORAGE_KEY, JSON.stringify({ exploredIds: appState.exploredIds, savedIds: appState.savedIds, reflections: appState.reflections, sparkQuestions: appState.sparkQuestions, streak: appState.streak, lastActiveDate: appState.lastActiveDate })); } catch(e) {} }
function updateLearnerProgress() { var count = appState.exploredIds.length; var rank = "Curious Observer 🔭"; var nextGoal = 10; if (count >= 50) { rank = "Ikshvaku Polymath 🏛️"; nextGoal = 100; } else if (count >= 25) { rank = "Natural Philosopher 🌌"; nextGoal = 50; } else if (count >= 10) { rank = "Scientific Explorer 🔬"; nextGoal = 25; } else if (count >= 3) { rank = "Inquisitive Thinker 💡"; nextGoal = 10; }
var pct = Math.min(100, Math.round((count / nextGoal) * 100)); var rankEl = document.getElementById('ivaLearnerRankTitle'); var fillEl = document.getElementById('ivaLearnerProgressFill'); var labelEl = document.getElementById('ivaLearnerXpLabel');
if (rankEl) rankEl.textContent = rank; if (fillEl) fillEl.style.width = pct + "%"; if (labelEl) labelEl.textContent = count + " / " + nextGoal + " Explored";
var expEl = document.getElementById('ivaJourneyExplored'); var refEl = document.getElementById('ivaJourneyReflections'); var savEl = document.getElementById('ivaJourneySaved'); var strEl = document.getElementById('ivaJourneyStreak'); var badEl = document.getElementById('ivaSavedBadge');
if (expEl) expEl.textContent = count; if (refEl) refEl.textContent = Object.keys(appState.reflections).length; if (savEl) savEl.textContent = appState.savedIds.length; if (strEl) strEl.textContent = appState.streak; if (badEl) badEl.textContent = "(" + appState.savedIds.length + ")"; }
// ════════════════════════════════════════════════════════════════ // 8. TOAST NOTIFICATION // ════════════════════════════════════════════════════════════════ var toastTimer = null; function showToast(icon, msg) { var toast = document.getElementById('ivaToast'); if (!toast) return; document.getElementById('ivaToastIcon').textContent = icon || "✨"; document.getElementById('ivaToastMessage').textContent = msg; toast.classList.remove('iva-hidden'); clearTimeout(toastTimer); toastTimer = setTimeout(function() { toast.classList.add('iva-hidden'); }, 2800); }
// ════════════════════════════════════════════════════════════════ // 9. VIEW SWITCHING // ════════════════════════════════════════════════════════════════ function showView(viewId) { playSynthSound('click'); var views = ['ivaHomeView', 'ivaCuriosityView', 'ivaBoredView', 'ivaStrangeView', 'ivaSavedView', 'ivaCategoryView']; for (var i = 0; i < views.length; i++) { var v = document.getElementById(views[i]); if (v) { if (views[i] === viewId) v.classList.remove('iva-hidden'); else v.classList.add('iva-hidden'); } } var root = document.getElementById('iva-curiosity-machine'); if (root) root.scrollIntoView({ behavior: 'smooth', block: 'start' }); updateLearnerProgress(); }
// ════════════════════════════════════════════════════════════════ // 10. CURIOSITY DETAIL RENDERER // ════════════════════════════════════════════════════════════════ function openCuriosity(questionId, directObj) { playSynthSound('discover'); var q = directObj; if (!q) { // Find or generate var parts = questionId.split('-'); var num = parseInt(parts[1], 10) || 1; q = generateProceduralQuestion(num - 1); } appState.currentQuestionId = q.id; appState.currentQuestionObj = q;
if (appState.exploredIds.indexOf(q.id) === -1) { appState.exploredIds.push(q.id); saveState(); }
document.getElementById('ivaCuriosityCategoryBadge').className = "iva-today-badge " + (q.badgeClass || 'iva-badge-space'); document.getElementById('ivaCuriosityCategoryBadge').textContent = q.categoryLabel || "Inquiry"; document.getElementById('ivaCuriosityReadTime').textContent = "⏱️ " + (q.readTime || "3 min read"); document.getElementById('ivaCuriosityInquiryNumber').textContent = "Inquiry #" + (q.globalNumber || 1).toLocaleString(); document.getElementById('ivaCuriosityTitle').textContent = q.question; document.getElementById('ivaCuriosityPrompt').textContent = q.prompt;
var savedThought = appState.reflections[q.id] || ""; document.getElementById('ivaThinkInput').value = savedThought; document.getElementById('ivaThinkSavedStatus').style.display = savedThought ? "inline" : "none";
document.getElementById('ivaExpSimple').textContent = q.simple; document.getElementById('ivaExpMechanism').textContent = q.mechanism; document.getElementById('ivaExpFirstPrinciples').textContent = q.firstPrinciples; document.getElementById('ivaWhatIfText').textContent = q.whatIf; document.getElementById('ivaRealLifeText').textContent = q.realLife;
// Connected tags var tagsContainer = document.getElementById('ivaConnectedTags'); tagsContainer.innerHTML = ""; if (q.connectedTags) { q.connectedTags.forEach(function(t) { var btn = document.createElement('button'); btn.type = "button"; btn.className = "iva-connected-tag"; btn.textContent = "# " + t; btn.addEventListener('click', function() { document.getElementById('ivaSearchInput').value = t; showView('ivaHomeView'); performSearch(t); }); tagsContainer.appendChild(btn); }); }
// Toggle simulator mode simMode = (q.category === 'how' || q.category === 'tech') ? 'wave' : 'orbit'; document.getElementById('ivaSimModeLabel').textContent = simMode === 'wave' ? 'Wave Inversion Phase' : 'Gravitational Free Fall';
updateBookmarkButton(q.id); showView('ivaCuriosityView'); }
function updateBookmarkButton(qid) { var btn = document.getElementById('ivaBookmarkBtn'); if (!btn) return; if (appState.savedIds.indexOf(qid) !== -1) { btn.textContent = "✓ In Your Bookmarks"; btn.className = "iva-btn iva-btn-secondary iva-btn-small"; } else { btn.textContent = "🔖 Save Question"; btn.className = "iva-btn iva-btn-primary iva-btn-small"; } }
function toggleBookmark(qid) { var idx = appState.savedIds.indexOf(qid); if (idx === -1) { appState.savedIds.push(qid); showToast("🔖", "Added to your curiosity bookmarks!"); } else { appState.savedIds.splice(idx, 1); showToast("🗑️", "Removed from bookmarks"); } saveState(); updateBookmarkButton(qid); updateLearnerProgress(); }
// ════════════════════════════════════════════════════════════════ // 11. CATEGORY VIEW & PAGINATION (62,500 QUESTIONS) // ════════════════════════════════════════════════════════════════ var currentCatOffset = 0; var currentCatKey = 'space';
function openCategory(catKey) { currentCatKey = catKey; currentCatOffset = 0; var catInfo = CATEGORIES.find(function(c) { return c.key === catKey; }) || { label: catKey, badge: "iva-badge-space" };
document.getElementById('ivaCategoryViewBadge').className = "iva-today-badge " + catInfo.badge; document.getElementById('ivaCategoryViewBadge').textContent = catInfo.label; document.getElementById('ivaCategoryViewTitle').textContent = catInfo.label + " (62,500 Inquiries)";
var grid = document.getElementById('ivaCategoryQuestionsGrid'); grid.innerHTML = ""; loadCategoryBatch(); showView('ivaCategoryView'); }
function loadCategoryBatch() { var grid = document.getElementById('ivaCategoryQuestionsGrid'); var catKeys = ["space", "science", "math", "tech", "thinking", "how", "behavior", "nature"]; var catIdx = catKeys.indexOf(currentCatKey); if (catIdx === -1) catIdx = 0; var baseGlobal = (catIdx * 62500) + currentCatOffset;
for (var i = 0; i < 20; i++) { if (currentCatOffset + i >= 62500) break; var q = generateProceduralQuestion(baseGlobal + i); var card = document.createElement('div'); card.className = "iva-saved-item"; card.innerHTML = '<div style="margin-bottom:8px;"><span class="iva-today-badge ' + q.badgeClass + '">' + q.categoryLabel + '</span> <span style="font-size:0.75rem; color:#888;">#' + q.globalNumber.toLocaleString() + '</span></div>' + '<div style="font-weight:700; color:#fff; font-size:1.05rem; margin-bottom:8px;">' + q.question + '</div>' + '<div style="color:rgba(255,255,255,0.7); font-size:0.88rem; line-height:1.5;">' + q.simple + '</div>'; (function(item) { card.addEventListener('click', function() { openCuriosity(item.id, item); }); })(q); grid.appendChild(card); } currentCatOffset += 20;
var moreBtn = document.getElementById('ivaCategoryLoadMoreBtn'); if (moreBtn) { if (currentCatOffset < 62500) { moreBtn.style.display = "inline-flex"; moreBtn.textContent = "Load More Inquiries (" + currentCatOffset.toLocaleString() + " of 62,500) ↓"; } else { moreBtn.style.display = "none"; } } }
// ════════════════════════════════════════════════════════════════ // 12. SEARCH & DIRECT NUMBER JUMP // ════════════════════════════════════════════════════════════════ function performSearch(query) { var q = query.trim().toLowerCase(); var resultsBox = document.getElementById('ivaSearchResults'); var grid = document.getElementById('ivaSearchResultsGrid');
if (!q) { resultsBox.classList.add('iva-hidden'); grid.innerHTML = ""; return; }
// Number Jump Check var num = parseInt(q.replace(/#/g, ''), 10); if (!isNaN(num) && num >= 1 && num <= 500000) { var directQ = generateProceduralQuestion(num - 1); grid.innerHTML = '<div class="iva-search-result-item" style="border:2px solid var(--iva-accent2);">' + '<div class="iva-result-category"><span class="iva-today-badge ' + directQ.badgeClass + '">Direct Jump: #' + num.toLocaleString() + '</span></div>' + '<div style="color:#fff; font-weight:700; margin-top:6px;">' + directQ.question + '</div>' + '<div style="color:var(--iva-accent2); font-size:0.8rem; margin-top:4px;">Click to explore this inquiry →</div></div>'; grid.querySelector('.iva-search-result-item').addEventListener('click', function() { document.getElementById('ivaSearchInput').value = ""; resultsBox.classList.add('iva-hidden'); openCuriosity(directQ.id, directQ); }); resultsBox.classList.remove('iva-hidden'); return; }
// Keyword Search grid.innerHTML = ""; var matches = []; for (var i = 0; i < 200; i++) { var item = generateProceduralQuestion(i * 250); if (item.question.toLowerCase().indexOf(q) !== -1 || item.categoryLabel.toLowerCase().indexOf(q) !== -1) { matches.push(item); if (matches.length >= 6) break; } }
if (matches.length === 0) { grid.innerHTML = '<div style="padding:16px; color:rgba(255,255,255,0.6); text-align:center;">No direct matches found. Try entering any question number (1 - 500,000)!</div>'; } else { matches.forEach(function(m) { var el = document.createElement('div'); el.className = "iva-search-result-item"; el.innerHTML = '<span class="iva-today-badge ' + m.badgeClass + '" style="font-size:0.7rem; padding:2px 8px;">' + m.categoryLabel + '</span>' + '<div style="color:#fff; margin-top:6px; font-weight:600;">' + m.question + '</div>'; el.addEventListener('click', function() { document.getElementById('ivaSearchInput').value = ""; resultsBox.classList.add('iva-hidden'); openCuriosity(m.id, m); }); grid.appendChild(el); }); } resultsBox.classList.remove('iva-hidden'); }
// ════════════════════════════════════════════════════════════════ // 13. STRANGE FACTS & BORED CHALLENGES DATA // ════════════════════════════════════════════════════════════════ var STRANGE_FACTS = [ "A day on Venus is longer than a year on Venus: it takes Venus 243 Earth days to rotate once on its axis, but only 225 Earth days to orbit the Sun.", "If you removed all empty atomic space from every human on Earth, all 8 billion people would fit in the volume of a single sugar cube.", "Light takes roughly 100,000 years to travel from the Sun's core to its surface, bouncing through dense plasma, but only 8 minutes and 20 seconds to reach Earth.", "Sharks are older than trees. Sharks have existed for roughly 400 million years, while early proto-trees emerged 350 million years ago.", "Water can boil and freeze simultaneously at its thermodynamic 'triple point' (0.01°C and 0.006 atm).", "Cleopatra lived closer in time to the release of the first iPhone than to the construction of the Great Pyramid of Giza.", "You cannot hum while holding your nose closed.", "Neutron stars are so dense that a single teaspoon of neutron star material weighs roughly 6 billion tons on Earth." ];
var BORED_CHALLENGES = [ "Look at any shadow cast in the room right now. Notice the blurry penumbra around its borders. Why isn't the edge razor-sharp? (The light source has physical width; rays overlap.)", "Pick up any object within arm's reach. Trace backwards: how many distinct human discoveries (metallurgy, chemistry, logistics) had to occur for this exact item to exist?", "Stare at a single letter in this sentence without blinking for 20 seconds. Words start looking alien—this is 'Semantic Satiation', neural pattern fatigue.", "Close your eyes and listen to the farthest away sound you can detect. What physical vibration is generating that wave right now?", "Place a hand on the desk. Is it actually cold, or is it simply conducting heat away from your skin faster than air does? (Thermal conductivity vs true temperature)." ];
var CONCEPT_SPARKS = [ "Entropy", "Black Holes", "Honeybees", "Soundwaves", "Origami", "Quantum Spin", "DNA", "Photosynthesis", "Lightning", "Fibonacci", "Neural Networks", "Bioluminescence", "Time Dilation", "Primes", "Echoes" ];
// ════════════════════════════════════════════════════════════════ // 14. INITIALIZATION & EVENT LISTENERS // ════════════════════════════════════════════════════════════════ function init() { loadState(); initCosmicCanvas(); initSimCanvas();
// Render Categories var catGrid = document.getElementById('ivaCategoriesGrid'); if (catGrid) { catGrid.innerHTML = ""; CATEGORIES.forEach(function(c) { var chip = document.createElement('button'); chip.type = "button"; chip.className = "iva-category-chip"; chip.innerHTML = "<span style='font-size:1.4rem;'>" + c.icon + "</span> <div><div>" + c.label + "</div><div style='font-size:0.75rem; color:rgba(255,255,255,0.5);'>62,500 Inquiries</div></div>"; chip.addEventListener('click', function() { openCategory(c.key); }); catGrid.appendChild(chip); }); }
// Set Daily Curiosity var dailySeed = (new Date().getFullYear() * 1000) + (new Date().getMonth() * 31) + new Date().getDate(); var todayQ = generateProceduralQuestion(dailySeed % 500000); document.getElementById('ivaTodayQuestion').textContent = todayQ.question; document.getElementById('ivaTodayBadge').className = "iva-today-badge " + todayQ.badgeClass; document.getElementById('ivaTodayBadge').textContent = todayQ.categoryLabel; document.getElementById('ivaTodayExcerpt').textContent = todayQ.simple;
document.getElementById('ivaTodayExploreBtn').addEventListener('click', function(e) { e.stopPropagation(); openCuriosity(todayQ.id, todayQ); }); document.getElementById('ivaTodayCard').addEventListener('click', function() { openCuriosity(todayQ.id, todayQ); }); document.getElementById('ivaTodayRollBtn').addEventListener('click', function(e) { e.stopPropagation(); var randQ = generateProceduralQuestion(Math.floor(Math.random() * 500000)); document.getElementById('ivaTodayQuestion').textContent = randQ.question; document.getElementById('ivaTodayBadge').className = "iva-today-badge " + randQ.badgeClass; document.getElementById('ivaTodayBadge').textContent = randQ.categoryLabel; document.getElementById('ivaTodayExcerpt').textContent = randQ.simple; showToast("🎲", "Rolled a new daily inquiry!"); });
// Navigation buttons document.getElementById('ivaLogoBtn').addEventListener('click', function() { showView('ivaHomeView'); }); document.getElementById('ivaNavHomeBtn').addEventListener('click', function() { showView('ivaHomeView'); }); document.getElementById('ivaHeroExploreBtn').addEventListener('click', function() { openCuriosity(todayQ.id, todayQ); }); document.getElementById('ivaBackToBrowseBtn').addEventListener('click', function() { showView('ivaHomeView'); });
// Sound toggle document.getElementById('ivaSoundToggleBtn').addEventListener('click', function() { soundEnabled = !soundEnabled; this.textContent = soundEnabled ? "🔊 Sound" : "🔇 Muted"; showToast(soundEnabled ? "🔊" : "🔇", soundEnabled ? "Audio feedback enabled" : "Audio muted"); });
// Cosmic Surprise Leap var handleSurprise = function() { var randIndex = Math.floor(Math.random() * 500000); var randQ = generateProceduralQuestion(randIndex); openCuriosity(randQ.id, randQ); showToast("🎲", "Leaped to Inquiry #" + (randIndex + 1).toLocaleString() + " of 500,000!"); }; document.getElementById('ivaNavRandomBtn').addEventListener('click', handleSurprise); document.getElementById('ivaHeroSurpriseBtn').addEventListener('click', handleSurprise); document.getElementById('ivaRandomWalkBtn').addEventListener('click', handleSurprise); document.getElementById('ivaNextRandomBtn').addEventListener('click', handleSurprise);
// Direct Jump var jumpBtn = document.getElementById('ivaJumpBtn'); var jumpInp = document.getElementById('ivaJumpInput'); var doJump = function() { var val = parseInt(jumpInp.value, 10); if (isNaN(val) || val < 1 || val > 500000) { showToast("⚠️", "Please enter a number between 1 and 500,000"); return; } var jQ = generateProceduralQuestion(val - 1); openCuriosity(jQ.id, jQ); showToast("🚀", "Jumped directly to Inquiry #" + val.toLocaleString() + "!"); }; jumpBtn.addEventListener('click', doJump); jumpInp.addEventListener('keydown', function(e) { if (e.key === 'Enter') doJump(); });
// Search document.getElementById('ivaSearchInput').addEventListener('input', function(e) { performSearch(e.target.value); });
// Bored Mode var rollBored = function() { playSynthSound('click'); var b = BORED_CHALLENGES[Math.floor(Math.random() * BORED_CHALLENGES.length)]; document.getElementById('ivaBoredChallengeText').textContent = b; }; document.getElementById('ivaNavBoredBtn').addEventListener('click', function() { rollBored(); showView('ivaBoredView'); }); document.getElementById('ivaHeroBoredBtn').addEventListener('click', function() { rollBored(); showView('ivaBoredView'); }); document.getElementById('ivaNextBoredBtn').addEventListener('click', rollBored); document.getElementById('ivaBoredBackHomeBtn').addEventListener('click', function() { showView('ivaHomeView'); });
// Strange Facts var rollStrange = function() { playSynthSound('click'); var s = STRANGE_FACTS[Math.floor(Math.random() * STRANGE_FACTS.length)]; document.getElementById('ivaStrangeFactDisplay').textContent = s; }; document.getElementById('ivaNavStrangeBtn').addEventListener('click', function() { rollStrange(); showView('ivaStrangeView'); }); document.getElementById('ivaNextStrangeBtn').addEventListener('click', rollStrange); document.getElementById('ivaStrangeBackHomeBtn').addEventListener('click', function() { showView('ivaHomeView'); });
// Sparks var rollSparks = function() { var copy = CONCEPT_SPARKS.slice(); copy.sort(function() { return 0.5 - Math.random(); }); document.getElementById('ivaBuildSparks').textContent = copy.slice(0, 3).join(" • "); }; document.getElementById('ivaRerollSparksBtn').addEventListener('click', rollSparks); document.getElementById('ivaSaveSparkQuestionBtn').addEventListener('click', function() { var txt = document.getElementById('ivaBuildTextarea').value.trim(); if (!txt) { showToast("⚠️", "Please write your question first!"); return; } appState.sparkQuestions.push(txt); document.getElementById('ivaBuildTextarea').value = ""; saveState(); showToast("✨", "Your question was recorded in your journal!"); });
// Reveal Explanation & Save Reflection document.getElementById('ivaRevealExplanationBtn').addEventListener('click', function() { playSynthSound('reveal'); var thought = document.getElementById('ivaThinkInput').value.trim(); if (thought && appState.currentQuestionId) { appState.reflections[appState.currentQuestionId] = thought; saveState(); document.getElementById('ivaThinkSavedStatus').style.display = "inline"; updateLearnerProgress(); showToast("💡", "Reflection penned to your intellectual journal!"); } document.getElementById('ivaExplanationContainer').scrollIntoView({ behavior: 'smooth', block: 'start' }); });
// Bookmarks document.getElementById('ivaBookmarkBtn').addEventListener('click', function() { if (appState.currentQuestionId) toggleBookmark(appState.currentQuestionId); });
// Saved View var renderSaved = function() { var grid = document.getElementById('ivaSavedGrid'); grid.innerHTML = ""; if (appState.savedIds.length === 0) { document.getElementById('ivaSavedEmpty').style.display = "block"; return; } document.getElementById('ivaSavedEmpty').style.display = "none"; appState.savedIds.forEach(function(sid) { var parts = sid.split('-'); var n = parseInt(parts[1], 10) || 1; var q = generateProceduralQuestion(n - 1); var card = document.createElement('div'); card.className = "iva-saved-item"; card.innerHTML = '<span class="iva-today-badge ' + q.badgeClass + '">' + q.categoryLabel + '</span>' + '<div style="font-weight:700; color:#fff; font-size:1.05rem; margin:8px 0;">' + q.question + '</div>' + '<div style="color:rgba(255,255,255,0.7); font-size:0.88rem;">' + q.simple + '</div>'; card.addEventListener('click', function() { openCuriosity(q.id, q); }); grid.appendChild(card); }); }; document.getElementById('ivaNavSavedBtn').addEventListener('click', function() { renderSaved(); showView('ivaSavedView'); }); document.getElementById('ivaSavedBackHomeBtn').addEventListener('click', function() { showView('ivaHomeView'); }); document.getElementById('ivaSavedExploreNowBtn').addEventListener('click', function() { showView('ivaHomeView'); });
// Category Back & Load More document.getElementById('ivaCategoryBackHomeBtn').addEventListener('click', function() { showView('ivaHomeView'); }); document.getElementById('ivaCategoryLoadMoreBtn').addEventListener('click', loadCategoryBatch);
// Share link document.getElementById('ivaShareBtn').addEventListener('click', function() { var shareUrl = window.location.href.split('#')[0] + '#curiosity-' + appState.currentQuestionId; if (navigator.clipboard && navigator.clipboard.writeText) { navigator.clipboard.writeText(shareUrl).then(function() { showToast("📋", "Inquiry link copied to clipboard!"); }); } else { prompt("Copy direct link:", shareUrl); } });
// Export Card Modal document.getElementById('ivaExportCardBtn').addEventListener('click', function() { if (!appState.currentQuestionObj) return; var thought = document.getElementById('ivaThinkInput').value.trim(); generateInsightCardPng(appState.currentQuestionObj, thought); document.getElementById('ivaCardModalOverlay').classList.remove('iva-hidden'); }); document.getElementById('ivaCardModalCloseBtn').addEventListener('click', function() { document.getElementById('ivaCardModalOverlay').classList.add('iva-hidden'); }); document.getElementById('ivaCardDoneBtn').addEventListener('click', function() { document.getElementById('ivaCardModalOverlay').classList.add('iva-hidden'); }); document.getElementById('ivaDownloadCardPngBtn').addEventListener('click', function() { var canvas = document.getElementById('ivaExportCardCanvas'); var a = document.createElement('a'); a.download = 'Ikshvaku-Curiosity-' + (appState.currentQuestionId || 'Inquiry') + '.png'; a.href = canvas.toDataURL('image/png'); a.click(); showToast("📥", "Insight Card downloaded!"); });
// Focus / Zen mode document.getElementById('ivaZenModeBtn').addEventListener('click', function() { var isZen = document.body.classList.toggle('iva-zen-active'); this.textContent = isZen ? "☀️ Exit Focus" : "🌙 Focus Mode"; showToast(isZen ? "🌙" : "☀️", isZen ? "Focus mode enabled" : "Standard mode restored"); });
// About Modal document.getElementById('ivaNavAboutBtn').addEventListener('click', function() { document.getElementById('ivaAboutModalOverlay').classList.remove('iva-hidden'); }); document.getElementById('ivaAboutCloseBtn').addEventListener('click', function() { document.getElementById('ivaAboutModalOverlay').classList.add('iva-hidden'); }); document.getElementById('ivaAboutGotItBtn').addEventListener('click', function() { document.getElementById('ivaAboutModalOverlay').classList.add('iva-hidden'); });
// Sim slider var simSlider = document.getElementById('ivaSimSlider'); if (simSlider) { simSlider.addEventListener('input', function(e) { var v = parseInt(e.target.value, 10); document.getElementById('ivaSimSliderVal').textContent = v + "%"; simSpeed = 0.005 + (v * 0.0008); }); }
updateLearnerProgress(); }
if (document.readyState === 'loading') { document.addEventListener('DOMContentLoaded', init); } else { init(); } })(); //
